    pts=[(r,c) for r in range(h) for c in range(w) if g[r][c]!=bg and (r,c) not in barcells]
    out=[row[:] for row in g]
    # bottom bar
    bb=[b for b in bars if b[0]==max(bars,key=lambda b:b[0])]
    b=bb[0]; bw=b[1]-b[0]
    sb = b[0]  # shift base = subtract bw+1
    for (r,c) in pts:
        orig_col=c
        ncol=(c-(bw+1))%w
        # fill translated column between bars (exclusive)
        for rr in range(bars[0][0]+1, bars[-1][0]):
